(function(){
const dayIndex=n=>Math.floor(new Date().setHours(0,0,0,0)/86400000)%n;
const ar='الله|الرَّحْمَنُ|الرَّحِيمُ|الْمَلِكُ|الْقُدُّوسُ|السَّلَامُ|الْمُؤْمِنُ|الْمُهَيْمِنُ|الْعَزِيزُ|الْجَبَّارُ|الْمُتَكَبِّرُ|الْخَالِقُ|الْبَارِئُ|الْمُصَوِّرُ|الْغَفَّارُ|الْقَهَّارُ|الْوَهَّابُ|الرَّزَّاقُ|الْفَتَّاحُ|اَلْعَلِيمُ|الْقَابِضُ|الْبَاسِطُ|الْخَافِضُ|الرَّافِعُ|الْمُعِزُّ|المُذِلُّ|السَّمِيعُ|الْبَصِيرُ|الْحَكَمُ|الْعَدْلُ|اللَّطِيفُ|الْخَبِيرُ|الْحَلِيمُ|الْعَظِيمُ|الْغَفُورُ|الشَّكُورُ|الْعَلِيُّ|الْكَبِيرُ|الْحَفِيظُ|المُقيِت|الْحسِيبُ|الْجَلِيلُ|الْكَرِيمُ|الرَّقِيبُ|الْمُجِيبُ|الْوَاسِعُ|الْحَكِيمُ|الْوَدُودُ|الْمَجِيدُ|الْبَاعِثُ|الشَّهِيدُ|الْحَقُّ|الْوَكِيلُ|الْقَوِيُّ|الْمَتِينُ|الْوَلِيُّ|الْحَمِيدُ|الْمُحْصِي|الْمُبْدِئُ|الْمُعِيدُ|الْمُحْيِي|اَلْمُمِيتُ|الْحَيُّ|الْقَيُّومُ|الْوَاجِدُ|الْمَاجِدُ|الْواحِدُ|اَلاَحَدُ|الصَّمَدُ|الْقَادِرُ|الْمُقْتَدِرُ|الْمُقَدِّمُ|الْمُؤَخِّرُ|الأوَّلُ|الآخِرُ|الظَّاهِرُ|الْبَاطِنُ|الْوَالِي|الْمُتَعَالِي|الْبَرُّ|التَّوَابُ|الْمُنْتَقِمُ|العَفُوُّ|الرَّؤُوفُ|مَالِكُ الْمُلْكِ|ذُوالْجَلَالِ وَالإكْرَامِ|الْمُقْسِطُ|الْجَامِعُ|الْغَنِيُّ|الْمُغْنِي|اَلْمَانِعُ|الضَّارَّ|النَّافِعُ|النُّورُ|الْهَادِي|الْبَدِيعُ|اَلْبَاقِي|الْوَارِثُ|الرَّشِيدُ|الصَّبُورُ'.split('|');esma.forEach((x,i)=>x.arabic=ar[i]||'');
let riyaz=[];fetch('/riyazus.json').then(r=>r.json()).then(x=>{riyaz=x;if(guideKind==='hadis')renderDuas()}).catch(console.warn);
function card(tag,cls,text){const e=document.createElement(tag);e.className=cls||'';if(text!=null)e.textContent=text;return e}
renderDuas=function(){const list=$('dua-list');list.replaceChildren();const tools=card('div','hadith-tools');const input=document.createElement('input');input.placeholder='Metin, ravi veya kaynak ara';const select=document.createElement('select');tools.append(input,select);list.append(tools);const cards=card('div','library-cards');list.append(cards);
 const paint=()=>{cards.replaceChildren();const term=normalize(input.value),topic=select.value;if(guideKind==='dua'){tools.classList.add('single');select.hidden=true;bigDuas.filter(x=>!term||normalize(`${x.title} ${x.text||''} ${x.source}`).includes(term)).forEach(x=>{let t=x.text;if(x.surah)t=state.corpus?.surahs[x.surah-1]?.ayahs[x.ayah-1]?.tr||x.title;const c=card('article','dua-card');c.append(card('span','dua-reference',`${x.kind} · ${x.source}`),card('h2','',x.title),card('p','dua-translation',t));cards.append(c)});}else if(guideKind==='hadis'){tools.classList.remove('single');select.hidden=false;(riyaz.length?riyaz:bigHadiths).filter(x=>(!topic||x.topic===topic)&&(!term||normalize(`${x.text} ${x.source} ${x.topic||''}`).includes(term))).forEach(x=>{const c=card('article','dua-card hadith-card');c.append(card('span','dua-reference',`Riyâzü’s-Sâlihîn · Cilt ${x.volume||1} · Hadis ${x.number||''}`),card('h3','hadith-topic',x.topic||x.category||'Hadis'),card('p','hadith-text',x.text),card('p','hadith-narrator',`Kaynak: ${x.source}`));cards.append(c)});}else{tools.classList.add('single');select.hidden=true;esma.filter(x=>!term||normalize(`${x.name} ${x.arabic} ${x.meaning}`).includes(term)).forEach((x,i)=>{const c=card('article','dua-card esma-card');c.append(card('span','dua-reference',`${i+1}/99 · Esmâü’l-Hüsnâ`),card('p','esma-arabic',x.arabic),card('h2','',x.name),card('p','dua-translation',x.meaning));cards.append(c)});}};
 if(guideKind==='hadis'){select.innerHTML='<option value="">Bütün konular</option>';[...new Set((riyaz.length?riyaz:bigHadiths).map(x=>x.topic||x.category))].sort((a,b)=>a.localeCompare(b,'tr')).forEach(x=>select.add(new Option(x,x)));}input.oninput=paint;select.onchange=paint;paint();};
document.querySelectorAll('[data-content]').forEach(b=>b.onclick=()=>{guideKind=b.dataset.content;document.querySelectorAll('[data-content]').forEach(x=>x.classList.toggle('active',x===b));renderDuas()});
function setDaily(kind){const d=document.getElementById('daily-content');if(!d)return;if(kind==='ayet'){const qs=bigDuas.filter(x=>x.surah),x=qs[dayIndex(qs.length)],surah=state.corpus?.surahs[x.surah-1],v=surah?.ayahs[x.ayah-1];d.innerHTML=`<b>Günün ayeti</b><h3>${v?.tr||x.title}</h3><p>${surah?.name||names[x.surah-1]} Suresi, ${x.ayah}. ayet</p>`;}else if(kind==='esma'){const x=esma[dayIndex(esma.length)];d.innerHTML=`<b>Esmâü’l-Hüsnâ</b><div class="daily-arabic">${x.arabic}</div><h3>${x.name}</h3><p>${x.meaning}</p>`;}}
document.querySelectorAll('[data-day="ayet"],[data-day="esma"]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-day]').forEach(x=>x.classList.toggle('active',x===b));setDaily(b.dataset.day)});setTimeout(()=>setDaily('ayet'),400);

const panel=$('audio-panel'),actions=panel?.querySelector('.audio-actions');if(actions){const picker=document.createElement('div');picker.className='reciter-pickers';picker.innerHTML='<label>Arapça kârî<select id="arabic-reciter"><option value="ar.alafasy">Mişârî Râşid el-Afâsî</option><option value="ar.abdulbasitmurattal">Abdülbâsıt Abdüssamed</option><option value="ar.husary">Mahmûd Halîl el-Husarî</option><option value="ar.minshawi">Muhammed Sıddîk el-Minşâvî</option></select></label><label>Türkçe meal sesi<select id="turkish-reciter"><option value="tr.vakfi-audio">Türkiye Diyanet Vakfı sesli meal</option></select></label>';panel.insertBefore(picker,actions);}
function arabicUrl(s){return `https://cdn.islamic.network/quran/audio-surah/128/${$('arabic-reciter')?.value||'ar.alafasy'}/${s.number}.mp3`}
$('play-arabic').onclick=()=>{const s=selectedSurah();if(!s)return;const p=$('quran-audio');p.onended=null;p.src=arabicUrl(s);p.hidden=false;p.load();p.play().catch(()=>setStatus('Ses başlatılamadı.'))};
$('download-arabic').onclick=e=>{const s=selectedSurah();if(!s)return;e.currentTarget.href=arabicUrl(s);e.currentTarget.download=`${s.number}-${s.name}-${$('arabic-reciter').value}.mp3`};
$('play-turkish').onclick=()=>{const s=selectedSurah();if(!s)return;let i=0;const p=$('quran-audio');p.hidden=false;const next=()=>{if(i>=s.ayahs.length){setStatus(`${s.name} suresinin Türkçe meali tamamlandı.`);return;}const a=s.ayahs[i++];p.src=`https://cdn.islamic.network/quran/audio/128/tr.vakfi-audio/${a.global}.mp3`;p.load();const go=()=>p.play().catch(()=>setStatus('Türkçe ses başlatılamadı.'));p.oncanplay=go;};p.onended=next;p.onerror=()=>setTimeout(next,200);next();setStatus(`${s.name} suresinin Türkçe meali kesintisiz oynatılıyor.`)};
})();

